import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static int K;
    static long N;
    static Matrix[] a = new Matrix[70], pre = new Matrix[70], suf = new Matrix[70];
    static Matrix r, em;

    static class Matrix {
        int[][] m = new int[33][33];

        Matrix() {
            for (int i = 0; i < 33; i++) {
                for (int j = 0; j < 33; j++) {
                    m[i][j] = 0;
                }
            }
        }
    }

    static void iprint(Matrix x) {
        for (int i = 0; i <= K; i++) {
            for (int j = 0; j <= K; j++) {
                System.out.print(x.m[i][j] + " ");
            }
            System.out.println();
        }
        System.out.println();
    }

    static Matrix imulti(Matrix a, Matrix b) {
        Matrix c = new Matrix();
        for (int k = 0; k <= K; k++) {
            for (int i = 0; i <= K; i++) {
                for (int j = 0; j <= K; j++) {
                    long tmp = ((long) a.m[i][k] * b.m[k][j]) % MOD;
                    c.m[i][j] = (int) ((c.m[i][j] + tmp) % MOD);
                }
            }
        }
        return c;
    }

    static void ical() {
        int i;
        pre[0] = a[0];
        for (i = 1; i < K; i++) {
            pre[i] = imulti(pre[i - 1], a[i]);
        }
        suf[K - 1] = a[K - 1];
        for (i = K - 2; i >= 0; i--) {
            suf[i] = imulti(a[i], suf[i + 1]);
        }
        a[0] = suf[0];
        for (i = 1; i < K; i++) {
            a[i] = imulti(suf[i], pre[i - 1]);
        }
    }

    static void iWork(Scanner sc) {
        N = sc.nextLong();
        K = sc.nextInt();

        em = new Matrix();
        r = new Matrix();

        for (int i = 0; i < 70; i++) {
            a[i] = new Matrix();
            pre[i] = new Matrix();
            suf[i] = new Matrix();
        }

        for (int i = 0; i < K; i++) {
            a[i] = new Matrix();
            for (int j = 0; j <= K; j++) {
                a[i].m[j][j] = 1;
                a[i].m[j][i] = 1;
            }
            r.m[i][i] = 1;
        }
        r.m[K][K] = 1;

        while (N > 0) {
            long tmpN = N;
            int tt = (int) (N % K);
            N /= K;
            if (tt != 0) {
                long pos = 0;
                long tmp = tmpN;
                while (tmp > 0) {
                    tmp /= K;
                    pos = (pos + tmp) % K;
                }
                for (int i = tt - 1; i >= 0; i--) {
                    r = imulti(a[(int) ((pos + i) % K)], r);
                }
            }
            ical();
        }

        int ans = 1;
        for (int i = 0; i < K; i++) {
            ans = (ans + r.m[K][i]) % MOD;
        }
        System.out.println(ans);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        iWork(sc);
        sc.close();
    }
}

